("62", "diagnostic-imaging-centers", "Diagnostic Imaging Centers", "621512", {},
 "Not `urgent-care` or `physician-practices`: covers freestanding imaging centers (MRI, CT, X-ray, mammography) where radiologist reads, prior authorisation and scanner utilisation run the business.", ""),
("62", "ambulance-services", "Ambulance Services", "621910", {},
 "Not `non-emergency-medical-transport`: covers 911 and interfacility ambulance services (BLS, ALS, air) billed under the Medicare ambulance fee schedule.", ""),
("62", "blood-and-organ-banks", "Blood & Organ Banks", "621991", {},
 "Not `clinical-laboratories`: covers blood centers, plasma centers and organ procurement organisations whose donor recruitment, testing and FDA/AABB compliance are the work.", ""),
("62", "health-screening-services", "Health Screening Services", "621999", {},
 "Not `urgent-care` or `physician-practices`: covers mobile and employer screening services (biometric screening, hearing and vision, sleep testing, health fairs) that test populations rather than treat patients.", "Screening services are the clearest firm type in this residual code."),
("62", "general-hospitals", "General Hospitals", "622110", {},
 "Not `urgent-care` or `physician-practices`: covers acute-care hospitals with inpatient beds, emergency departments and surgery, paid by DRGs and commercial contracts.", ""),
("62", "psychiatric-hospitals", "Psychiatric Hospitals", "622210", {},
 "Not `behavioral-health-clinics` or `residential-treatment-centers`: covers inpatient psychiatric and substance-use hospitals paid under the IPF PPS, with involuntary-hold law and 24-hour nursing.", ""),
("62", "specialty-hospitals", "Specialty Hospitals", "622310", {},
 "Not `general-hospitals`: covers inpatient rehab, long-term acute care, children's, cancer and orthopedic hospitals with their own CMS payment systems (IRF-PAI, LTCH PPS).", ""),
("62", "skilled-nursing-facilities", "Skilled Nursing Facilities", "623110", {},
 "Not `home-health-agencies` or `assisted-living-communities`: covers SNFs paid under PDPM, run on MDS assessments and rated by CMS Five-Star.", ""),
("62", "assisted-living-communities", "Assisted Living Communities", "623312",
 {"623311": "CCRCs run assisted and independent living with the same private-pay sales, care staffing and state AL licensing, plus an entrance-fee contract."},
 "Not `skilled-nursing-facilities` or `home-health-agencies`: covers state-licensed assisted living and memory care, mostly private pay.", ""),
("62", "idd-group-homes", "IDD Group Homes", "623210", {},
 "Not `nonprofits-social-services` or `home-health-agencies`: covers ICF/IID facilities and Medicaid HCBS-waiver group homes for people with intellectual and developmental disabilities, staffed by direct support professionals.", ""),
("62", "residential-treatment-centers", "Residential Treatment Centers", "623220", {},
 "Not `behavioral-health-clinics` or `psychiatric-hospitals`: covers residential substance-use and mental-health programs billing ASAM levels of care to insurers and Medicaid.", ""),
("62", "youth-group-homes", "Youth Group Homes", "623990", {},
 "Not `nonprofits-social-services` or `idd-group-homes`: covers child-welfare-funded group homes, residential care and halfway houses paid per diem by state agencies.", ""),
# ---------------- 53 Real Estate, Rental & Leasing ----------------
("53", "self-storage-operators", "Self-Storage Operators", "531130", {},
 "Not `commercial-real-estate` or `property-management`: covers self-storage owner-operators and third-party managers whose street-rate management, existing-customer rent increases, lien auctions and unmanned access are the business.", ""),
("53", "car-rental-companies", "Car Rental Companies", "532111", {},
 "Not `rideshare-fleet-operators` or `fleet-managers`: covers daily-rental fleets (airport, neighbourhood, insurance replacement) run on utilisation, damage recovery and remarketing.", ""),
("53", "truck-and-trailer-lessors", "Truck, Trailer & RV Lessors", "532120", {},
 "Not `car-rental-companies` or `fleet-managers`: covers commercial truck full-service leasing, one-way moving-truck rental and RV rental, with DOT maintenance obligations on the lessor.", ""),
("53", "rent-to-own-stores", "Rent-to-Own Stores", "532210",
 {"532289": "Furniture and other consumer-goods rental runs on the same weekly-payment lease agreements, collections and returns."},
 "Not `bnpl-providers` or `independent-retailers`: covers rent-to-own stores and lease-to-own providers under state RTO laws, where weekly collections and merchandise recovery are the work.", ""),
("53", "formal-wear-rental-shops", "Formal Wear & Costume Rental Shops", "532281", {},
 "Not `alterations-tailoring`: covers tux, gown and costume rental shops whose fitting, alteration and turnaround logistics around event dates are the work.", ""),
("53", "recreational-rental-shops", "Recreational Equipment Rental Shops", "532284", {},
 "Not `equipment-rental-companies`: covers bike, kayak, ski, paddleboard and beach rental outfits with seasonal, weather-driven demand and waiver-based liability.", ""),
("53", "equipment-rental-companies", "Equipment Rental Companies", "532412",
 {"532310": "General rental centers (tool and party rental) run the same fleet utilisation, dispatch, damage-waiver and maintenance workflow, often from the same branches.",
  "532490": "Other commercial and industrial equipment rental (generators, forklifts, medical and test equipment) is the same rental business with a different fleet."},
 "Not `construction-tech-platforms` or `fleet-managers`: covers branch-based renters of construction, industrial and general equipment whose time-utilisation and dollar-utilisation are the business.", ""),
("53", "aircraft-and-railcar-lessors", "Aircraft & Railcar Lessors", "532411", {},
 "Not `equipment-rental-companies` or `asset-managers`: covers operating lessors of aircraft, engines, railcars and vessels whose residual values, maintenance reserves and redeliveries are the business.", ""),
("53", "franchisors", "Franchisors", "533110", {},
 "Not `independent-restaurants` or `hair-salons-independent`, which hold franchisees: covers franchisor head offices that sell and support franchises, collect royalties and keep FDDs current under the FTC Franchise Rule.", "Franchisors are the largest operator population in this code; patent and brand licensors are fewer."),
# ---------------- 71 Arts, Entertainment & Recreation ----------------
("71", "performing-arts-companies", "Performing Arts Companies", "711110",
 {"711120": "Dance companies run the same nonprofit season model (subscriptions, single tickets, grants, donor cultivation, venue rental) with the same administrative staff.",
  "711190": "Circuses, ice shows and other companies sell the same seasons and tours through the same ticketing and touring workflow."},
 "Not `event-planning` or `musical-groups`: covers theater, dance and other performing companies that produce their own seasons, funded by tickets, subscriptions and contributed income.", ""),
("71", "musical-groups", "Musical Groups & Orchestras", "711130", {},
 "Not `creator-businesses` or `music-distribution-platforms`: covers orchestras, bands and ensembles that earn from performances and touring, where booking, union scale and player scheduling are the work.", ""),
("71", "sports-teams", "Sports Teams & Clubs", "711211", {},
 "Not `youth-sports-orgs` or `esports-organizations`: covers professional and minor-league teams earning from tickets, sponsorship and media rights.", ""),
("71", "racetracks", "Racetracks", "711212", {},
 "Not `casinos` or `event-venues`: covers horse and motorsport tracks earning from pari-mutuel handle, purses and race-day events under state racing commissions.", ""),
("71", "racing-stables", "Racing Stables", "711219", {},
 "Not `racetracks` or `horse-breeding-farms`: covers racing stables and trainers who condition horses and enter races, living on purses and day rates.", "Racing stables and trainers are the largest operator group in this residual code."),
("71", "event-venues", "Event Venues", "711310", {},
 "Not `event-planning` or `hotels-boutique`: covers arenas, stadiums, amphitheaters and theaters that own facilities and book or co-promote events.", ""),
("71", "event-promoters", "Event Promoters", "711320", {},
 "Not `event-planning` or `creator-talent-agencies`: covers concert promoters and festival producers who take the ticket-sales risk on talent guarantees.", ""),
("71", "museums", "Museums", "712110",
 {"712120": "Historical sites and house museums do the same collections care, interpretation, admissions and membership work under the same AAM standards."},
 "Not `nonprofits-social-services`: covers art, history and science museums and historic sites whose collections, exhibitions, admissions and membership are the work.", ""),
("71", "zoos-and-botanical-gardens", "Zoos & Botanical Gardens", "712130",
 {"712190": "Nature parks and preserves run the same living-collection, grounds and admissions-plus-membership model."},
 "Not `museums`: covers zoos, aquariums, botanical gardens and nature parks whose living collections need daily husbandry or horticulture under AZA and USDA rules.", ""),
("71", "theme-parks", "Theme Parks", "713110", {},
 "Not `family-entertainment-centers`: covers ride-based amusement and water parks with ride-safety inspections, seasonal staffing and attendance-driven yield pricing.", ""),
("71", "family-entertainment-centers", "Family Entertainment Centers", "713120",
 {"713950": "Bowling centers now run as FECs (lanes plus arcade plus party bookings plus food and drink) with the same game-card, party-booking and F&B workflow.",
  "713990": "Trampoline parks, escape rooms, go-karts, mini golf and laser tag sell the same per-visit and party-package experiences."},
 "Not `gyms-independent` or `theme-parks`: covers arcades, bowling centers and indoor attractions that sell games, parties and group events.", ""),
("71", "casinos", "Casinos", "713210",
 {"721120": "Casino hotels run the same gaming floor, player tracking, comps and gaming-commission compliance; the hotel is an amenity of the floor."},
 "Not `hotels-boutique` or `gambling-operators`: covers land-based casinos and casino resorts licensed by state or tribal gaming commissions.", ""),
("71", "gambling-operators", "Sportsbooks & Other Gambling Operators", "713290", {},
 "Not `casinos`: covers online and retail sportsbooks, bingo halls, off-track betting and slot-route operators, where odds-setting and responsible-gaming compliance are the work.", ""),
("71", "golf-clubs", "Golf Courses & Country Clubs", "713910", {},
 "Not `gyms-independent`: covers golf courses and member clubs run on tee sheets, dues, F&B minimums and turf agronomy.", ""),
("71", "ski-resorts", "Ski Resorts", "713920", {},
 "Not `theme-parks`: covers ski areas whose snowmaking, lift operations and season-pass economics turn on weather.", ""),
("71", "marinas", "Marinas", "713930", {},
 "Not `powersports-and-boat-dealers` or `self-storage-operators`: covers marinas and dry-stack storage selling slips, fuel and boat service.", ""),
# ---------------- 81 Other Services ----------------
("81", "auto-glass-shops", "Auto Glass Shops", "811122", {},
 "Not `auto-body-shops`: covers windshield replacement and repair shops, mostly mobile, billed to insurers through glass networks and now recalibrating ADAS cameras after each install.", ""),
("81", "quick-lube-shops", "Quick Lube Shops", "811191", {},
 "Not `auto-repair-shops`: covers fast oil-change shops whose ten-minute bays, upsell menus and car-count economics differ from diagnostic repair.", ""),
("81", "car-washes", "Car Washes", "811192", {},
 "Not `auto-body-shops`: covers express tunnel, in-bay automatic and full-service washes, increasingly run on unlimited-wash memberships.", ""),
("81", "electronics-repair-shops", "Electronics Repair Shops", "811210", {},
 "Not `it-managed-services`: covers phone, computer and precision-equipment repair shops paid per repair, with parts sourcing and right-to-repair constraints.", ""),
("81", "industrial-repair-shops", "Industrial Machinery Repair Shops", "811310", {},
 "Not `metal-fabrication` or `field-service-software`: covers motor-rewind, pump, gearbox, hydraulic and machinery repair shops that fix plant equipment, much of it on emergency turnaround.", ""),
("81", "appliance-repair-companies", "Appliance Repair Companies", "811412", {},
 "Not `hvac-contractors`: covers in-home appliance technicians paid per call by homeowners and by warranty companies on fixed authorisations.", ""),
("81", "upholstery-shops", "Upholstery Shops", "811420", {},
 "Not `alterations-tailoring` or `cleaning-companies`: covers furniture, auto, marine and commercial reupholstery and furniture repair shops quoting by yardage and labour.", ""),
("81", "shoe-repair-shops", "Shoe Repair Shops", "811430", {},
 "Not `alterations-tailoring`: covers cobblers and leather-goods repair shops whose resoling, stitching and finishing are a separate craft.", ""),
("81", "nail-salons", "Nail Salons", "812113", {},
 "Not `hair-salons-independent` or `med-spas`: covers nail salons, mostly owner-operated, with walk-in flow, product chemistry exposure and state cosmetology-board rules.", ""),
("81", "weight-loss-centers", "Weight Loss Centers", "812191", {},
 "Not `med-spas` or `gyms-independent`: covers diet and weight-management centers, now split between coaching programs and GLP-1 prescribing clinics.", ""),
("81", "cemeteries-and-crematories", "Cemeteries & Crematories", "812220", {},
 "Not `funeral-homes`: covers cemeteries and crematories selling plots, niches and pre-need contracts and maintaining grounds under perpetual-care trust rules.", ""),
("81", "laundromats", "Laundromats", "812310", {},
 "Not `drycleaners`: covers coin and card-operated laundries, many adding wash-and-fold and pickup-and-delivery.", ""),
("81", "drycleaners", "Drycleaners", "812320", {},
 "Not `laundromats` or `alterations-tailoring`: covers drycleaning and laundry plants and drop stores, with solvent regulation and spotting as a craft.", ""),
("81", "commercial-laundries", "Commercial Laundries", "812331",
 {"812332": "Industrial launderers (uniform rental) run the same plants, route trucks and rental-garment tracking as linen suppliers."},
 "Not `cleaning-companies` or `laundromats`: covers linen and uniform rental services that own the textiles, launder them in industrial plants and deliver on routes.", ""),
("81", "photo-labs", "Photo Labs", "812921",
 {"812922": "One-hour labs do the same film processing and printing for the same customers."},
 "Not `printing-shops` or `portrait-photography-studios`: covers film-processing and photo-printing labs, from pro labs to the film-revival mail-in labs.", ""),
("81", "parking-operators", "Parking Operators", "812930", {},
 "Not `property-management` or `commercial-real-estate`: covers operators who run lots and garages under management or lease contracts, with yield pricing, enforcement and revenue control.", ""),
("81", "bail-bond-agencies", "Bail Bond Agencies", "812990", {},
 "Not `collections-agencies` or `public-defenders`: covers licensed bail agents who post surety bonds for defendants, take collateral and recover skips.", "Bail agents are the largest licensed firm type in this residual code."),
("81", "grantmaking-foundations", "Grantmaking Foundations", "813211",
 {"813219": "United Ways, community foundations and other giving services run the same grant cycles, due diligence and impact reporting."},
 "Not `grant-writers` or `nonprofits-social-services`: covers private, family and community foundations that make grants rather than deliver services.", ""),
("81", "advocacy-nonprofits", "Advocacy Nonprofits", "813319",
 {"813212": "Voluntary health organisations run the same donor fundraising (walks, peer-to-peer, direct mail) and advocacy campaigns, plus research grants.",
  "813311": "Human rights organisations run the same donor-funded campaign and advocacy model.",
  "813312": "Conservation organisations raise money and campaign the same way; land trusts' stewardship is one niche within."},
 "Not `nonprofits-social-services` or `trade-associations`: covers cause organisations that fundraise from individuals and run campaigns rather than deliver services or represent an industry.", ""),
("81", "civic-and-fraternal-clubs", "Civic & Fraternal Clubs", "813410", {},
 "Not `trade-associations` or `faith-organizations`: covers service clubs, fraternal lodges, alumni and social clubs that live on dues, volunteers and events.", ""),
("81", "labor-unions", "Labor Unions", "813930", {},
 "Not `trade-associations` or `hr-consultants`: covers unions and locals that organise, bargain contracts, process grievances and run hiring halls and benefit funds.", ""),
("81", "political-campaigns", "Political Campaigns & Committees", "813940", {},
 "Not `advocacy-nonprofits` or `marketing-agencies-smb`: covers candidate campaigns, parties and PACs, which raise under FEC or state limits and spend against an election date.", ""),
# ---------------- 72 Accommodation & Food Services ----------------
("72", "bed-and-breakfasts", "Bed-and-Breakfasts", "721191", {},
 "Not `hotels-boutique` or `short-term-rentals`: covers owner-occupied inns where the innkeeper cooks, cleans and sells, with a handful of rooms.", ""),
("72", "rv-parks-and-campgrounds", "RV Parks & Campgrounds", "721211", {},
 "Not `rv-dealerships` or `short-term-rentals`: covers RV parks and campgrounds selling sites by the night, month and season, with utility hookups and seasonal staff.", ""),
("72", "summer-camps", "Summer & Vacation Camps", "721214", {},
 "Not `childcare-centers` or `youth-sports-orgs`: covers overnight and day camps with seasonal staff hiring, ACA accreditation and a once-a-year enrollment cycle.", ""),
("72", "workforce-housing-operators", "Workforce Housing Operators", "721310", {},
 "Not `property-management` or `short-term-rentals`: covers workers' camps, dormitories, rooming houses and co-living operators that sell beds to employers or individuals.", ""),
("72", "contract-food-service-operators", "Contract Food Service Operators", "722310", {},
 "Not `catering-companies` or `independent-restaurants`: covers contract dining for schools, hospitals, campuses, prisons and stadiums under multi-year management or P&L contracts.", ""),
("72", "bars-and-taverns", "Bars & Taverns", "722410", {},
 "Not `independent-restaurants`: covers drinking places whose liquor-licence, pour-cost and late-night labour economics differ from food-led restaurants.", ""),
# ---------------- 42 Wholesale Trade ----------------
("42", "wholesale-auto-auctions", "Wholesale Auto Auctions", "423110", {},
 "Not `auto-dealers-independent` or `online-marketplaces`: covers physical and digital dealer-only auctions that condition-grade, arbitrate and settle used-vehicle trades between dealers, fleets and lenders.", ""),
("42", "auto-parts-distributors", "Auto Parts Distributors & Stores", "423120",
 {"423130": "Tire wholesalers deliver to the same repair shops and dealers with the same fitment lookup and hot-shot routes.",
  "441330": "Parts chains (NAPA, O'Reilly, AutoZone) earn a growing share from commercial delivery to repair shops, the same fitment and hot-shot work as warehouse distributors."},
 "Not `auto-repair-shops` or `tire-dealers`: covers aftermarket parts distributors and parts stores whose fitment catalog, inventory depth and delivery speed win the shop's call.", ""),
("42", "auto-salvage-yards", "Auto Salvage Yards", "423140", {},
 "Not `towing-companies` or `scrap-metal-recyclers`: covers auto recyclers who buy wrecked vehicles, dismantle and inventory parts by interchange, and sell to shops and the public.", ""),
("42", "home-furnishings-wholesalers", "Home Furnishings Wholesalers", "423210",
 {"423220": "Home furnishing wholesalers sell through the same market-week showrooms and reps to the same furniture and home stores."},
 "Not `furniture-stores` or `dropshipping-suppliers`: covers furniture and home-goods wholesalers and importers selling to retailers through showrooms and markets.", ""),
("42", "building-material-dealers", "Building Material Dealers", "423310",
 {"423320": "Brick, stone and masonry supply yards sell to the same contractors with the same takeoff, quote and job-site delivery.",
  "423330": "Roofing, siding and insulation distributors do the same two-step distribution to contractors from branch yards.",
  "423390": "Other construction material distributors run the same contractor-account, quote and delivery workflow.",
  "444180": "Lumberyards and pro dealers that NAICS files as retail do the same takeoff, quote, yard and job-site delivery work for contractors."},
 "Not `general-contractors` or `construction-tech-platforms`: covers lumberyards, pro dealers and building-material distributors that sell to contractors on account with job-site delivery.", ""),
("42", "business-equipment-dealers", "Office & Business Equipment Dealers", "423420",
 {"423440": "Cash-register, scale, ATM and store-fixture dealers sell, install and service machines under service contracts like copier dealers.",
  "532420": "Copier and office-machine leasing is done by the same dealers as part of the sale."},
 "Not `it-managed-services` or `printing-shops`: covers copier, MFP and business-machine dealers that sell or lease equipment and earn on click-charge service contracts.", ""),
("42", "it-value-added-resellers", "IT Distributors & Value-Added Resellers", "423430", {},
 "Not `it-managed-services` or `saas-implementation-partners`: covers distributors and VARs that resell hardware and licences on thin margins, earning on vendor rebates and attached services.", ""),
("42", "medical-supply-distributors", "Medical Supply Distributors", "423450",
 {"423460": "Ophthalmic goods wholesalers sell regulated product catalogs to the same practices.",
  "423490": "Lab and other professional supply distributors sell regulated catalogs to clinics and labs under the same GPO contracts."},
 "Not `medical-supply-retail` or `pharmaceutical-wholesalers`: covers med-surg, dental, lab and ophthalmic distributors that supply providers, not patients.", ""),
("42", "metal-service-centers", "Metal Service Centers", "423510", {},
 "Not `metal-fabrication`: covers service centers that buy mill steel and aluminum, cut and process it to order, and deliver next day to fabricators and OEMs.", ""),
("42", "electrical-distributors", "Electrical Distributors", "423610", {},
 "Not `electrical-contractors`: covers electrical supply houses selling wire, gear and lighting to contractors and plants, with project quoting and counter sales.", ""),
("42", "consumer-goods-wholesalers", "Consumer Goods Wholesalers", "423620",
 {"423410": "Camera and photo-equipment distributors sell to the same retailers through the same rep-and-EDI channel.",
  "423910": "Sporting goods wholesalers sell branded goods to specialty retailers through reps, trade shows and seasonal pre-books.",
  "423920": "Toy and hobby wholesalers use the same rep, trade-show and pre-book channel to the same independents.",
  "423990": "Other durable-goods wholesalers (luggage, instruments, housewares) sell through the same channel.",
  "424990": "Other nondurable wholesalers (pet, art and party supplies) sell through the same channel.",
  "424920": "Book and periodical distributors sell to the same independent retailers on returnable terms."},
 "Not `dropshipping-suppliers` or `independent-retailers`: covers wholesalers and importers of consumer goods that sell to retailers on account through reps, trade shows and EDI.", ""),
("42", "electronic-component-distributors", "Electronic Component Distributors", "423690", {},
 "Not `electronics-contract-mfg`: covers broadline and catalog distributors of chips and passives, plus independent brokers, whose allocation, counterfeit screening and design-in support are the work.", ""),
("42", "hardware-wholesalers", "Hardware Wholesalers", "423710", {},
 "Not `hardware-stores`: covers hardware wholesalers and retailer-owned co-ops that supply independent hardware stores from regional DCs.", ""),
("42", "plumbing-and-hvac-distributors", "Plumbing & HVAC Distributors", "423720",
 {"423730": "HVAC equipment distributors sell to the same mechanical contractors (NAICS 238220 lumps plumbing and HVAC) from the same branch model.",
  "423740": "Refrigeration supply houses sell to the same HVAC/R contractors."},
 "Not `plumbing-contractors` or `hvac-contractors`: covers supply houses that sell pipe, fixtures, equipment and parts to mechanical contractors from branches.", ""),
("42", "heavy-equipment-dealers", "Construction Equipment Dealers", "423810", {},
 "Not `equipment-rental-companies`: covers OEM-franchised construction and mining equipment dealers living on parts and service, rental fleets and equipment sales.", ""),
("42", "farm-equipment-dealers", "Farm Equipment Dealers", "423820", {},
 "Not `crop-farming` or `agtech-platforms`: covers OEM-franchised farm and turf equipment dealers whose service department, used trade-ins and precision-ag support are the business.", ""),
("42", "industrial-distributors", "Industrial Distributors", "423840",
 {"423830": "Industrial machinery and equipment distributors sell to the same plant maintenance and engineering buyers, often from the same branches."},
 "Not `procurement-spend-platforms`: covers MRO, bearings, power-transmission, fluid-power and industrial-equipment distributors that keep plants running.", ""),
("42", "aviation-parts-distributors", "Aircraft & Marine Parts Distributors", "423860", {},
 "Not `aircraft-mro-shops`: covers distributors of certified aircraft, marine and rail parts, where traceability paperwork (8130-3 tags) is part of the product.", ""),
("42", "scrap-metal-recyclers", "Scrap Metal Recyclers", "423930",
 {"423520": "Coal and ore merchants trade bulk raw materials to the same mills and smelters, grading and pricing loads against commodity indexes."},
 "Not `recycling-facilities` or `auto-salvage-yards`: covers scrap yards and processors that buy, grade, shred and broker ferrous and nonferrous metal to mills.", ""),
("42", "business-supplies-distributors", "Business Supplies Distributors", "424130",
 {"424110": "Paper merchants sell printing paper through the same warehouses, reps and delivery as packaging and facility supplies.",
  "424120": "Office-supply wholesalers and dealers sell to the same business buyers on the same contract-delivery model.",
  "459410": "Office supply chains earn most of their revenue through B2B contract delivery, the same work as independent dealers."},
 "Not `procurement-spend-platforms` or `cleaning-companies`: covers distributors and dealers of packaging, janitorial, breakroom and office supplies sold to businesses on contract.", ""),
("42", "pharmaceutical-wholesalers", "Pharmaceutical Wholesalers", "424210", {},
 "Not `pharmacy-independents` or `medical-supply-distributors`: covers drug wholesalers operating under DSCSA serialisation, DEA controlled-substance rules and state wholesaler licences.", ""),
("42", "apparel-wholesalers", "Apparel & Footwear Wholesalers", "424350",
 {"424340": "Footwear wholesalers sell through the same showrooms, line sheets, pre-books and EDI to the same retailers.",
  "424310": "Fabric converters and notions jobbers sell into the same garment supply chain through the same showroom-and-sample model."},
 "Not `d2c-brand-operators` or `apparel-manufacturers`: covers wholesalers and importers selling apparel and footwear to retailers by season.", ""),
("42", "grain-elevators", "Grain Elevators & Farm Product Merchants", "424510",
 {"424590": "Cotton, wool, leaf-tobacco and hay merchants buy raw farm products from growers with the same grading, price-risk and storage work.",
  "493130": "Farm product warehousing under the US Warehouse Act is the same licensed storage, grading and receipting."},
 "Not `crop-farming` or `commodity-brokers`: covers country and terminal elevators and farm-product merchants that buy, store, grade and hedge growers' crops.", ""),
("42", "livestock-auction-markets", "Livestock Auction Markets", "424520", {},
 "Not `livestock-operations`: covers sale barns, video auctions and order buyers that price and move cattle and other livestock between producers, feedlots and packers.", ""),
("42", "chemical-distributors", "Chemical Distributors", "424690",
 {"424610": "Resin and plastics distributors do the same bulk and packaged distribution, repackaging and SDS and hazmat compliance."},
 "Not `environmental-consultants` or `specialty-chemical-blenders`: covers distributors that buy, store, repackage and deliver industrial chemicals and resins.", ""),
("42", "fuel-distributors", "Petroleum Fuel Distributors", "424720",
 {"424710": "Bulk plants and terminals are owned and run by the same jobbers as part of the same supply chain."},
 "Not `owner-operator-trucking` or `convenience-stores`: covers petroleum jobbers that buy rack fuel and deliver to stations, fleets and farms.", ""),
("42", "beverage-alcohol-distributors", "Beverage Alcohol Distributors", "424810",
 {"424820": "Wine and spirits distributors work the same three-tier system, route sales, chain programming and depletion reporting."},
 "Not `food-distributors`: covers beer, wine and spirits wholesalers in the three-tier system, bound by state franchise laws and ABC rules.", ""),
("42", "ag-input-retailers", "Ag Input Retailers", "424910",
 {"325314": "Fertilizer blending plants are run by the same ag retailers and co-ops as part of their agronomy service."},
 "Not `crop-farming` or `agtech-platforms`: covers ag retailers and co-ops selling seed, fertilizer and crop protection with agronomy advice and custom application.", ""),
("42", "floral-wholesalers", "Floral Wholesalers", "424930", {},
 "Not `greenhouse-horticulture` or `florists`: covers wholesalers and importers moving perishable cut flowers and supplies from growers and Miami importers to florists.", ""),
("42", "convenience-store-distributors", "Convenience Store Distributors", "424940", {},
 "Not `food-distributors`: covers tobacco, candy and c-store distributors that handle tax-stamping, age-restricted products and weekly route delivery.", ""),
("42", "manufacturers-reps", "Manufacturers' Representatives", "425120", {},
 "Not `staffing-agencies` or `b2b-commerce-platforms`: covers independent rep agencies that sell several manufacturers' lines in a territory for commission, plus wholesale brokers.", ""),
# ---------------- 44-45 Retail Trade ----------------
("44", "franchised-car-dealers", "Franchised Car Dealers", "441110", {},
 "Not `auto-dealers-independent`: covers OEM-franchised new-car dealers bound by franchise agreements, floorplan, CSI scores and OEM incentive programs.", ""),
("44", "powersports-and-boat-dealers", "Powersports & Boat Dealers", "441227",
 {"441222": "Boat dealers run the same OEM floorplan, seasonal inventory, F&I and service-department model, often in the same store."},
 "Not `rv-dealerships`: covers motorcycle, ATV, side-by-side and boat dealers with seasonal, floorplan-financed inventory.", ""),
("44", "tire-dealers", "Tire Dealers", "441340", {},
 "Not `auto-repair-shops` or `auto-parts-distributors`: covers tire stores that sell and install tires and do alignment, where inventory by size and bay throughput drive the business.", ""),
("44", "hardware-stores", "Hardware Stores & Home Centers", "444140",
 {"444110": "Home centers run the same assortment, special-order and pro-desk workflow at scale."},
 "Not `independent-retailers` or `hardware-wholesalers`: covers hardware stores and home centers selling to DIY customers and trades.", ""),
("44", "paint-stores", "Paint Stores", "444120",
 {"424950": "Paint jobbers sell to the same painting and body-shop contractors with the same tinting and color matching."},
 "Not `painting-contractors`: covers paint stores and jobbers whose color matching and contractor accounts are the business.", ""),
("44", "outdoor-power-equipment-dealers", "Outdoor Power Equipment Dealers", "444230",
 {"811411": "Small-engine repair shops are mostly OPE dealers' service departments or independents doing the same repairs for the same homeowners and landscapers."},
 "Not `landscaping`: covers mower, chainsaw and handheld equipment dealers and small-engine repair shops.", ""),
("44", "garden-centers", "Garden Centers & Farm Stores", "444240", {},
 "Not `greenhouse-horticulture` or `landscaping`: covers garden centers and farm-and-ranch stores selling live goods, soil, feed and supplies with spring-peak demand.", ""),
("44", "grocery-stores", "Grocery Stores", "445110", {},
 "Not `specialty-food-retail` or `food-distributors`: covers supermarkets and grocery stores, independents and chains, with perishable shrink, DSD vendors and thin margins.", ""),
("44", "convenience-stores", "Convenience Stores & Gas Stations", "445131",
 {"457110": "Gas stations with convenience stores are the same operators running fuel plus in-store on the same POS and back office.",
  "457120": "Fuel-only stations are run by the same operators under the same fuel-pricing and compliance work."},
 "Not `coffee-shops-independent`: covers c-store and fuel retailers whose fuel pricing, lottery, tobacco and age-restricted compliance are the work.", ""),
("44", "vending-machine-operators", "Vending Machine Operators", "445132", {},
 "Not `convenience-stores`: covers route-based vending and micro-market operators restocking machines at client sites.", ""),
("44", "liquor-stores", "Liquor Stores", "445320", {},
 "Not `specialty-food-retail`: covers beer, wine and liquor retailers bound by state ABC licensing and three-tier pricing.", ""),
("44", "furniture-stores", "Furniture Stores", "449110",
 {"449129": "Home furnishings stores (kitchenware, lighting, decor) sell through the same showroom, special-order and delivery model."},
 "Not `independent-retailers` or `home-furnishings-wholesalers`: covers furniture and home-furnishings retailers with special orders, white-glove delivery and financing.", ""),
("44", "flooring-and-blinds-retailers", "Flooring & Window Covering Retailers", "449121",
 {"449122": "Window treatment retailers do the same in-home measure, quote, order and installer scheduling."},
 "Not `flooring-contractors` or `painting-contractors`: covers showrooms that sell flooring and window coverings to homeowners and subcontract installation.", ""),
("44", "appliance-and-electronics-stores", "Appliance & Electronics Stores", "449210", {},
 "Not `appliance-repair-companies`: covers appliance and electronics retailers selling with delivery, installation and extended warranties.", ""),
("44", "general-merchandise-retailers", "General Merchandise Chains", "455219",
 {"455110": "Department stores run the same central merchandising, replenishment and store-operations machinery.",
  "455211": "Warehouse clubs and supercenters run the same central merchandising and replenishment at larger scale."},
 "Not `independent-retailers`: covers dollar, variety, department and warehouse-club chains run from a central merchandising office.", ""),
("44", "beauty-supply-stores", "Beauty Supply Stores", "456120", {},
 "Not `hair-salons-independent`: covers beauty-supply and cosmetics retailers selling to consumers and licensed stylists.", ""),
("44", "optical-retailers", "Optical Retailers", "456130", {},
 "Not `optometry-practices`: covers optical shops and opticians selling eyewear, where frame inventory, lab turnaround and vision-plan billing are the work.", ""),
("44", "supplement-stores", "Supplement Stores", "456191", {},
 "Not `pharmacy-independents`: covers vitamin and supplement retailers working within DSHEA claim limits.", ""),
("44", "propane-and-heating-oil-dealers", "Propane & Heating Oil Dealers", "457210", {},
 "Not `hvac-contractors` or `fuel-distributors`: covers home-delivery fuel dealers whose degree-day delivery scheduling and tank monitoring are the business.", ""),
("44", "jewelry-stores", "Jewelry Stores", "458310", {},
 "Not `independent-retailers` or `jewelry-manufacturers`: covers jewelry retailers selling bridal, fashion and repair, with memo inventory and appraisal work.", ""),
("44", "sporting-goods-stores", "Sporting Goods Stores", "459110", {},
 "Not `independent-retailers` or `youth-sports-orgs`: covers sporting goods retailers and team dealers selling uniforms and equipment to schools and leagues.", ""),
("44", "hobby-and-craft-stores", "Hobby, Game & Craft Stores", "459120",
 {"459130": "Sewing and quilt shops run the same class-and-event-driven community model with specialty inventory."},
 "Not `independent-retailers`: covers hobby, game, toy, craft and fabric stores that live on events, classes and enthusiast inventory.", ""),
("44", "musical-instrument-stores", "Musical Instrument Stores", "459140", {},
 "Not `independent-retailers` or `fine-arts-schools`: covers instrument retailers whose school rental programs, lessons and repair shops matter as much as sales.", ""),
("44", "bookstores", "Bookstores", "459210", {},
 "Not `independent-publishers`: covers book retailers and news dealers working on returnable inventory, events and thin margins.", ""),
("44", "florists", "Florists", "459310", {},
 "Not `greenhouse-horticulture` or `floral-wholesalers`: covers retail florists whose perishable inventory, wire-service orders and event work run the business.", ""),
("44", "thrift-and-resale-stores", "Thrift & Resale Stores", "459510", {},
 "Not `recommerce-platforms`: covers thrift, consignment, antique and resale stores pricing one-of-a-kind donated or consigned goods.", ""),
("44", "pet-stores", "Pet Stores", "459910", {},
 "Not `pet-services`: covers pet food and supply retailers, some selling live animals under state pet-shop rules.", ""),
("44", "art-galleries", "Art Galleries", "459920", {},
 "Not `creator-businesses` or `auctioneers`: covers galleries and art dealers selling on consignment and setting prices for living artists.", ""),
("44", "manufactured-home-dealers", "Manufactured Home Dealers", "459930", {},
 "Not `rv-dealerships` or `factory-built-home-builders`: covers retailers selling HUD-code homes with chattel financing, site prep and installation.", ""),
("44", "smoke-and-vape-shops", "Smoke & Vape Shops", "459991", {},
 "Not `convenience-stores`: covers tobacco, vape and smoke shops working under FDA deeming rules, age verification and fast-changing state flavour bans.", ""),
# ---------------- 48-49 Transportation & Warehousing ----------------
("48", "passenger-airlines", "Passenger Airlines", "481111", {},
 "Not `charter-air-operators`: covers scheduled Part 121 airlines run on revenue management, crew scheduling and network planning.", ""),
("48", "air-cargo-carriers", "Air Cargo Carriers", "481112",
 {"481212": "Nonscheduled freight charters (ACMI and ad hoc) are flown by the same cargo airlines with the same crews and aircraft."},
 "Not `freight-brokerage` or `last-mile-delivery`: covers scheduled and charter cargo airlines that fly freight for integrators, forwarders and shippers.", ""),
("48", "charter-air-operators", "Charter & On-Demand Air Operators", "481211",
 {"481219": "Other nonscheduled flying under Part 135 and Part 91 is done by the same on-demand operators."},
 "Not `passenger-airlines`: covers Part 135 charter, fractional and on-demand operators selling whole-aircraft trips.", ""),
("48", "freight-railroads", "Freight Railroads", "482112",
 {"482111": "Class I railroads run the same FRA-regulated train, yard and car-hire operations at larger scale."},
 "Not `owner-operator-trucking`: covers short-line, regional and Class I freight railroads.", ""),
("48", "rail-services-contractors", "Rail Services Contractors", "488210", {},
 "Not `freight-railroads`: covers railcar repair shops, switching and transload operators and maintenance-of-way contractors serving railroads and shippers.", ""),
("48", "ocean-shipping-carriers", "Ocean Shipping Carriers", "483111", {},
 "Not `customs-brokers` or `freight-brokerage`: covers deep-sea carriers operating vessels, US-flag and international.", ""),
("48", "tug-and-barge-operators", "Tug & Barge Operators", "483211",
 {"483113": "Coastal and Great Lakes freight is mostly tug-and-barge under the Jones Act and USCG Subchapter M, the same as inland towing."},
 "Not `ocean-shipping-carriers`: covers towboat and barge operators on rivers, lakes and coasts.", ""),
("48", "cruise-lines", "Cruise Lines", "483112",
 {"483114": "Coastal small-ship cruises run the same berth inventory, itinerary and onboard-revenue model."},
 "Not `hotels-boutique` or `ferry-operators`: covers ocean and coastal cruise lines selling cabins and onboard spend.", ""),
("48", "ferry-operators", "Ferry Operators", "483212", {},
 "Not `cruise-lines` or `transit-agencies`: covers inland and harbor ferries and water taxis moving passengers and vehicles on fixed routes.", ""),
("48", "boat-tour-operators", "Boat Tour & Fishing Charter Operators", "487210", {},
 "Not `ferry-operators` or `tour-operators`: covers sightseeing cruises, whale watching, dinner cruises and fishing charters run by USCG-licensed captains.", ""),
("48", "ltl-carriers", "LTL Carriers", "484122", {},
 "Not `owner-operator-trucking` or `freight-brokerage`: covers less-than-truckload carriers running terminal networks, linehaul and dock cross-docking with freight-class pricing.", ""),
("48", "transit-agencies", "Rail & Mixed-Mode Transit Agencies", "485111",
 {"485112": "Commuter rail systems run the same FTA-funded, FRA- or state-safety-overseen service planning and operations.",
  "485119": "Other urban transit (light rail, subway, streetcar) is run by the same transit authorities."},
 "Not `municipal-services`, which keeps bus-only systems: covers transit authorities running rail and mixed-mode networks under FTA funding and safety oversight.", ""),
("48", "school-bus-contractors", "School Bus Contractors", "485410", {},
 "Not `charter-bus-operators`: covers school-bus and employee-shuttle contractors bound by district contracts, routing and special-needs requirements.", ""),
("48", "pipeline-operators", "Pipeline Operators", "486210",
 {"486110": "Crude pipelines run the same PHMSA integrity management, control rooms and SCADA.",
  "486910": "Refined products pipelines run the same integrity, batching and control-room work.",
  "486990": "Other pipelines (NGLs, CO2) run under the same PHMSA regime.",
  "488999": "Independently operated pipeline terminals are the main operators in this residual code and do the same tankage and custody-transfer work."},
 "Not `oil-gas-field-services` or `utility-contractors`: covers interstate and intrastate pipeline operators.", ""),
("48", "sightseeing-tour-companies", "Land Sightseeing Companies", "487110", {},
 "Not `charter-bus-operators` or `tour-operators`: covers trolley, bus, scenic-railroad and carriage tour operators selling seats on fixed routes.", ""),
("48", "aerial-tour-operators", "Aerial & Other Sightseeing Operators", "487990", {},
 "Not `charter-air-operators`: covers helicopter tours, hot-air balloon rides and aerial tramways selling experiences rather than transport.", ""),
("48", "airport-operators", "Airport Operators", "488119",
 {"488111": "Contract air-traffic towers are bought by the same airport sponsors and run under the same FAA airport operations regime."},
 "Not `municipal-services`: covers airport authorities and operators running airfields and terminals, plus contract towers.", ""),
("48", "aircraft-mro-shops", "Aircraft MRO & FBO Shops", "488190", {},
 "Not `airport-operators` or `aviation-parts-distributors`: covers aircraft maintenance, repair and overhaul shops and FBOs, where A&P mechanics and FAA Part 145 rules govern the work.", ""),
("48", "port-terminal-operators", "Port & Terminal Operators", "488320",
 {"488310": "Port and harbor operators run the same berths, yards and gates as stevedores, often as landlords to them."},
 "Not `customs-brokers` or `warehouse-3pl`: covers stevedores, marine terminal operators and port authorities.", ""),
("48", "marine-pilotage-and-towing", "Harbor Pilots & Towing Services", "488330",
 {"488390": "Salvage, ship-assist and other water support services run from the same harbor tug and pilot bases."},
 "Not `tug-and-barge-operators`: covers harbor pilots, ship-assist tugs and salvage operators serving vessels in port.", ""),
("48", "toll-road-operators", "Toll Road & Bridge Operators", "488490", {},
 "Not `municipal-services` or `highway-contractors`: covers toll-road, bridge and tunnel operators and concessionaires running tolling and roadway operations.", ""),
("48", "crating-and-export-packers", "Crating & Export Packers", "488991", {},
 "Not `moving-companies` or `warehouse-3pl`: covers industrial crating and export-packing firms building ISPM-15 crates for machinery and project cargo.", ""),
# ---------------- 23 Construction ----------------
("23", "land-developers", "Land Developers", "237210", {},
 "Not `general-contractors` or `commercial-real-estate`: covers developers who entitle raw land, subdivide it and install infrastructure for sale as lots.", ""),
("23", "highway-contractors", "Highway & Bridge Contractors", "237310", {},
 "Not `utility-contractors` or `general-contractors`: covers contractors who bid DOT lettings for roads and bridges, with prevailing wage and DBE rules.", ""),
("23", "heavy-civil-contractors", "Heavy Civil Contractors", "237990", {},
 "Not `highway-contractors` or `utility-contractors`: covers marine, dam, rail and other heavy civil builders.", ""),
("23", "concrete-contractors", "Concrete Contractors", "238110", {},
 "Not `general-contractors`: covers poured-concrete foundation and flatwork subcontractors whose pour scheduling and finishing are the trade.", ""),
("23", "steel-erectors", "Structural Steel & Ironwork Erectors", "238120",
 {"238190": "Ornamental metal, curtain-wall framing and on-site welding work is done by the same ironworkers and crews."},
 "Not `metal-fabrication`: covers erectors and ironworkers who raise steel and precast on site.", ""),
("23", "framing-contractors", "Framing Contractors", "238130", {},
 "Not `general-contractors`: covers wood and light-gauge framing subcontractors paid per square foot.", ""),
("23", "masonry-contractors", "Masonry Contractors", "238140", {},
 "Not `concrete-contractors`: covers brick, block and stone masons.", ""),
("23", "glazing-contractors", "Glazing Contractors", "238150", {},
 "Not `general-contractors`: covers glass and curtain-wall installers working from shop drawings.", ""),
("23", "siding-contractors", "Siding Contractors", "238170", {},
 "Not `roofing-contractors`: covers siding, gutter and exterior-trim installers.", ""),
("23", "elevator-contractors", "Elevator Contractors", "238290",
 {"333921": "Elevator OEMs earn most of their margin installing and servicing their own units, the same mechanic work as independent elevator contractors."},
 "Not `electrical-contractors`: covers elevator and escalator installers and service contractors.", ""),
("23", "drywall-and-insulation-contractors", "Drywall & Insulation Contractors", "238310", {},
 "Not `painting-contractors`: covers drywall hangers, finishers, acoustical-ceiling and insulation installers.", ""),
("23", "flooring-contractors", "Flooring Contractors", "238330", {},
 "Not `flooring-and-blinds-retailers`: covers commercial and builder flooring installers working for GCs and builders.", ""),
("23", "tile-contractors", "Tile & Terrazzo Contractors", "238340", {},
 "Not `flooring-contractors`: covers tile setters and terrazzo installers, a separate trade with its own waterproofing and layout skills.", ""),
("23", "finish-carpentry-contractors", "Finish Carpentry Contractors", "238350",
 {"238390": "Other building finishing (countertops, closet systems, shower doors) is installed by the same finish crews."},
 "Not `general-contractors`: covers trim, door, cabinet and countertop installers.", ""),
("23", "excavation-contractors", "Excavation & Site Prep Contractors", "238910", {},
 "Not `utility-contractors`: covers excavation, grading and demolition subcontractors.", ""),
("23", "paving-contractors", "Asphalt Paving Contractors", "238990", {},
 "Not `highway-contractors`: covers parking-lot and driveway paving and sealcoating contractors.", "Paving and sealcoating contractors are the largest firm type in this residual code; fence and pool builders also sit here."),
# ---------------- 22 Utilities ----------------
("22", "hydroelectric-operators", "Hydroelectric Operators", "221111", {},
 "Not `electric-utilities` or `thermal-power-plants`: covers owners and operators of hydro and pumped-storage plants under FERC licences, dam-safety inspections and water-release constraints, whose fuel is a reservoir level.", ""),
("22", "thermal-power-plants", "Fossil & Thermal Power Plants", "221112",
 {"221116": "Geothermal plants are steam-cycle plants run by the same control-room operators on the same turbine-generator sets.",
  "221117": "Biomass plants are steam boilers run like coal units by the same operators, with fuel handling as the main difference."},
 "Not `electric-utilities` or `nuclear-power-plants`: covers merchant and utility-owned gas, coal, biomass and geothermal plants that bid into wholesale markets and live on heat rate, availability and emissions permits.", ""),
("22", "nuclear-power-plants", "Nuclear Power Plants", "221113", {},
 "Not `thermal-power-plants`: covers nuclear plant operators under NRC licences, with refuelling outages, security and decommissioning trusts that no other generator carries.", ""),
("22", "renewable-power-producers", "Renewable Power Producers", "221114",
 {"221115": "Wind farms are owned and operated by the same IPPs under the same PPAs, interconnection queues, market bidding and remote SCADA O&M.",
  "221118": "Battery storage and other generation is developed and operated by the same IPPs under the same contracts and market rules."},
 "Not `solar-installers` or `energy-auditors`: covers owners and operators of utility-scale solar, wind and battery storage that sell under PPAs or into wholesale markets and run their fleets remotely.", ""),
("22", "transmission-operators", "Transmission & Grid Operators", "221121", {},
 "Not `electric-utilities` or `utility-contractors`: covers ISOs, RTOs and transmission owners that dispatch the grid, run wholesale markets and study interconnection under FERC and NERC rules.", ""),
("22", "electric-utilities", "Electric Distribution Utilities", "221122", {},
 "Not `utility-contractors` or `municipal-services`: covers investor-owned, cooperative and municipal distribution utilities that bill retail customers under PUC-approved rates and restore outages.", ""),
("22", "gas-utilities", "Gas Distribution Utilities", "221210", {},
 "Not `electric-utilities` or `pipeline-operators`: covers local distribution companies that deliver gas to homes and businesses under PUC rates and PHMSA distribution-integrity rules.", ""),
("22", "district-energy-operators", "District Energy Operators", "221330", {},
 "Not `electric-utilities` or `hvac-contractors`: covers district steam, hot-water and chilled-water systems serving campuses and downtowns under long-term service contracts.", ""),
# ---------------- 21 Mining ----------------
("21", "oil-and-gas-producers", "Oil & Gas Producers", "211120",
 {"211130": "Natural gas producers run the same leasing, drilling, completion and production operations, usually in the same basins and often the same firms."},
 "Not `oil-gas-field-services`: covers E&P operators that hold leases, decide where to drill and hire service companies to do it, with royalty owners, state commissions and decline curves setting the clock.", ""),
("21", "coal-mines", "Coal Mines", "212114",
 {"212115": "Underground coal mines are run by the same operators under the same MSHA and SMCRA regime and the same supply contracts; roof control is the extra skill."},
 "Not `utility-contractors` or `mining-contractors`: covers surface and underground coal operators selling thermal and metallurgical coal on contract.", ""),
("21", "metal-mines", "Metal Mines", "212230",
 {"212210": "Iron ore mines run the same drill-blast-haul, grade control and concentrating work.",
  "212290": "Other metal mines (lithium, uranium, rare earths) run the same mine-and-mill workflow under the same MSHA rules."},
 "Not `mining-contractors` or `gold-and-silver-mines`: covers copper, iron, lithium and other metal mine-and-mill operators whose grade control and recovery decide the margin.", ""),
("21", "gold-and-silver-mines", "Gold & Silver Mines", "212220", {},
 "Not `metal-mines`: covers precious-metal operators from majors to junior and placer miners, with heap-leach and cyanide-code operations and spot-price exposure.", ""),
("21", "dimension-stone-quarries", "Dimension Stone Quarries", "212311", {},
 "Not `aggregate-producers` or `stone-countertop-fabricators`: covers quarries that cut granite, marble and limestone blocks and slabs, where block yield from each bench is the craft.", ""),
("21", "aggregate-producers", "Crushed Stone, Sand & Gravel Producers", "212312",
 {"212313": "Granite quarries run the same drill-blast, crushing, screening and stockpile sales.",
  "212319": "Other crushed stone quarries run the same operation for the same buyers.",
  "212321": "Sand and gravel pits sell to the same ready-mix, asphalt and DOT buyers through the same plant and scale house."},
 "Not `dimension-stone-quarries` or `ready-mix-concrete-producers`: covers crushed stone, sand and gravel producers selling by the ton within trucking distance.", ""),
("21", "industrial-mineral-mines", "Industrial Mineral Mines", "212390",
 {"212322": "Industrial sand miners process to customer specs (grain size, purity) for glass, foundry and oilfield buyers, the same work.",
  "212323": "Kaolin, clay and refractory mineral miners process to the same kind of customer specs.",
  "327992": "Ground and treated mineral processing is the mill at the mine, run by the same operators."},
 "Not `aggregate-producers`: covers miners of industrial sand, kaolin, potash, borates and other specialty minerals sold to specification rather than by the ton.", ""),
("21", "mining-contractors", "Mining Contractors", "213114",
 {"213113": "Coal mining support contractors do the same contract drilling, blasting and stripping.",
  "213115": "Nonmetallic mining support contractors do the same work for quarries and industrial-mineral mines.",
  "325920": "Commercial explosives makers sell mostly through their own blasting-service arms, the same drill-and-blast work."},
 "Not `oil-gas-field-services`: covers contract drillers, blasters and stripping contractors working for coal, metal and nonmetallic mine operators.", ""),
# ---------------- 11 Agriculture, Forestry & Fishing ----------------
("11", "fish-farms", "Fish Farms", "112511",
 {"112519": "Other aquaculture (shrimp and other species in ponds and RAS) runs the same water-quality, feeding and harvest workflow."},
 "Not `livestock-operations` or `commercial-fishing-operations`: covers finfish farms and hatcheries (catfish ponds, trout raceways, salmon RAS) where water quality and feed conversion run the business.", ""),
("11", "shellfish-farms", "Shellfish Farms", "112512", {},
 "Not `fish-farms`: covers oyster, clam and mussel growers on leased beds under state shellfish sanitation and NSSP rules, with Vibrio and harmful-algae closures.", ""),
("11", "beekeeping-operations", "Beekeeping Operations", "112910", {},
 "Not `crop-farming`: covers commercial beekeepers who earn from almond and other pollination contracts as well as honey, with colony losses as the main risk.", ""),
("11", "horse-breeding-farms", "Horse Farms & Equine Breeders", "112920", {},
 "Not `livestock-operations` or `racing-stables`: covers horse breeders, stallion stations and boarding farms whose bloodlines, foaling and sales preparation are the work.", ""),
("11", "specialty-livestock-farms", "Specialty Livestock Farms", "112990",
 {"112930": "Fur-bearing animal and rabbit farms raise niche livestock with the same small-herd husbandry and niche-market selling."},
 "Not `livestock-operations`: covers bison, deer, elk, alpaca, rabbit and other specialty animal farms with small herds and direct or niche markets.", ""),
("11", "timberland-managers", "Timberland Owners & Managers", "113110", {},
 "Not `logging-companies` or `forestry-services`: covers timberland owners, REITs and TIMOs that manage forests as long-dated assets and sell stumpage.", ""),
("11", "logging-companies", "Logging Companies", "113310", {},
 "Not `timberland-managers` or `sawmills`: covers logging contractors who cut and haul timber to mills, paid per ton under mill quotas.", ""),
("11", "commercial-fishing-operations", "Commercial Fishing Operations", "114111",
 {"114112": "Shellfish fishing vessels work under the same NOAA and state quotas, vessel monitoring and crew-share economics.",
  "114119": "Other marine fishing is done by the same vessel operators under the same regime."},
 "Not `fish-farms`: covers commercial fishing vessels under NOAA and state quotas, observer coverage and crew-share pay.", ""),
("11", "hunting-outfitters", "Hunting Preserves & Outfitters", "114210", {},
 "Not `family-entertainment-centers` or `specialty-livestock-farms`: covers hunting preserves, outfitters and guides selling hunts under state game-agency licences.", ""),
("11", "cotton-gins", "Cotton Gins", "115111", {},
 "Not `crop-farming` or `grain-elevators`: covers gins that clean and bale seed cotton for growers and send bales for USDA classing.", ""),
("11", "custom-farming-contractors", "Custom Farming Contractors", "115112",
 {"115113": "Custom harvesting crews are the same per-acre equipment contractors working the other end of the season."},
 "Not `crop-farming` or `farm-labor-contractors`: covers custom applicators, planters and harvest crews that own equipment and work farmers' fields by the acre.", ""),
("11", "produce-packing-houses", "Produce Packing Houses", "115114", {},
 "Not `food-manufacturing` or `crop-farming`: covers packers that sort, grade, cool and pack fresh produce for growers under FSMA produce-safety rules.", ""),
("11", "farm-labor-contractors", "Farm Labor Contractors", "115115", {},
 "Not `staffing-agencies`: covers farm labor contractors and crew leaders registered under MSPA, many running H-2A crews with housing and transport duties.", ""),
("11", "farm-management-firms", "Farm Management Firms", "115116", {},
 "Not `agtech-platforms` or `crop-farming`: covers professional farm managers who run farms for absentee and institutional landowners for a fee.", ""),
("11", "livestock-support-services", "Livestock Support Services", "115210", {},
 "Not `veterinary-practices` or `livestock-operations`: covers AI technicians, hoof trimmers, shearers, pregnancy checkers and custom feeders who sell skilled labour to producers.", ""),
("11", "forestry-services", "Forestry Services Contractors", "115310", {},
 "Not `logging-companies` or `timberland-managers`: covers consulting foresters, timber cruisers, reforestation crews and wildfire contractors.", ""),
# ---------------- 31-33 Manufacturing ----------------
("31", "beverage-bottlers", "Beverage Bottlers", "312111",
 {"312112": "Bottled water plants run the same high-speed filling lines, DSD routes and retailer programs, often inside the same bottler.",
  "312113": "Packaged ice makers freeze, bag and deliver on the same DSD route model to the same c-stores and grocers."},
 "Not `food-manufacturing`: covers soft-drink bottlers, bottled-water plants and packaged-ice makers whose high-speed lines and direct-store-delivery routes run the business.", ""),
("31", "breweries", "Breweries", "312120", {},
 "Not `food-manufacturing` or `bars-and-taverns`: covers production breweries and brewpubs under TTB permits, where recipe consistency, tank scheduling and distributor relationships are the work.", ""),
("31", "wineries", "Wineries", "312130", {},
 "Not `crop-farming` (vineyards) or `liquor-stores`: covers bonded wineries whose winemaking judgement, barrel programs and direct-to-consumer shipping compliance run the business.", ""),
("31", "distilleries", "Distilleries", "312140", {},
 "Not `breweries` or `beverage-alcohol-distributors`: covers distilled-spirits plants under TTB, where cut points, barrel ageing and federal excise tax are the work.", ""),
("31", "tobacco-manufacturers", "Tobacco Manufacturers", "312230", {},
 "Not `convenience-store-distributors` or `smoke-and-vape-shops`: covers cigarette, cigar, smokeless and e-liquid makers under FDA premarket tobacco rules and excise taxes.", ""),
("31", "textile-mills", "Textile Mills", "313210",
 {"313110": "Yarn spinning mills sell to the same weavers and knitters and run the same continuous mill floor and quality lab.",
  "313220": "Narrow-fabric and Schiffli embroidery mills weave and knit on the same kinds of machines for the same apparel and industrial buyers.",
  "313240": "Knit fabric mills make fabric for the same cut-and-sew buyers with the same lab dips, yield and defect grading.",
  "314994": "Rope, cordage and tire-cord mills twist and braid fiber on the same kind of continuous textile lines."},
 "Not `contract-manufacturing` or `apparel-manufacturers`: covers mills that spin, weave, knit and braid fiber into yarn and fabric for apparel, home and industrial buyers.", ""),
("31", "nonwoven-fabric-mills", "Nonwoven Fabric Mills", "313230", {},
 "Not `textile-mills`: covers spunbond, meltblown and needlepunch lines making roll goods for hygiene, filtration, medical and wipes buyers, a polymer-process business rather than weaving.", ""),
("31", "textile-dyers-and-finishers", "Textile Dyers & Finishers", "313310",
 {"313320": "Fabric coaters run the same commission finishing model on customers' greige goods, with chemistry and line control as the craft."},
 "Not `textile-mills`: covers commission dyehouses, printers, finishers and coaters that process other mills' fabric, where shade matching and right-first-time rates decide margin.", ""),
("31", "carpet-mills", "Carpet Mills", "314110", {},
 "Not `textile-mills` or `flooring-contractors`: covers tufting and weaving carpet mills, mostly around Dalton, Georgia, selling broadloom and tile to flooring retailers and contract buyers.", ""),
("31", "sewn-products-makers", "Sewn Textile Products Makers", "314120",
 {"314910": "Canvas, awning and textile-bag shops cut and sew non-apparel textiles to order with the same pattern, nesting and sewing workflow.",
  "314999": "Other textile product makers (flags, banners, contract embroidery) run the same small cut-and-sew shops.",
  "337920": "Blind and shade fabricators make made-to-measure window coverings with the same fabric cutting and sewing as drapery workrooms."},
 "Not `apparel-manufacturers` or `upholstery-shops`: covers cut-and-sew makers of curtains, bedding, awnings, canvas goods, flags and window coverings.", ""),
("31", "apparel-manufacturers", "Apparel Manufacturers", "315250",
 {"315120": "Apparel knitting mills (hosiery, sweaters) design, sample and sell garments to the same retailers and brands.",
  "315990": "Accessory makers (hats, gloves, belts, ties) run the same design, sampling and wholesale workflow."},
 "Not `contract-manufacturing` (cut-and-sew contractors) or `d2c-brand-operators`: covers apparel makers that own their designs and production, from tech pack to sample to bulk.", ""),
("31", "tanneries", "Tanneries", "316110", {},
 "Not `footwear-and-leather-goods-makers`: covers tanneries and leather finishers whose hide grading, tanning chemistry and wastewater permits run the business.", ""),
("31", "footwear-and-leather-goods-makers", "Footwear & Leather Goods Makers", "316210",
 {"316990": "Handbag, luggage and saddlery makers cut and stitch leather with the same clicking, skiving and stitching workflow."},
 "Not `tanneries` or `apparel-manufacturers`: covers makers of footwear, handbags, belts, luggage and saddlery.", ""),
("31", "sawmills", "Sawmills", "321113",
 {"321912": "Planing mills and resaw operations finish the same lumber with the same grading, kiln and planer work, often on the sawmill site."},
 "Not `logging-companies` or `building-material-dealers`: covers sawmills whose log bucking, sawing optimisation and lumber grading decide recovery.", ""),
("31", "wood-treating-plants", "Wood Treating Plants", "321114", {},
 "Not `sawmills`: covers pressure-treating plants applying preservatives (CCA, ACQ, creosote) under EPA FIFRA labels and AWPA standards.", ""),
("31", "engineered-wood-mills", "Engineered Wood & Panel Mills", "321212",
 {"321211": "Hardwood veneer and plywood mills run the same peeling, drying and press lines.",
  "321215": "Engineered wood member plants (glulam, LVL, I-joists) press veneers and strands into structural members under the same APA certification.",
  "321219": "OSB, particleboard and MDF plants run the same continuous press lines and resin chemistry."},
 "Not `sawmills`: covers plywood, OSB, MDF and engineered-lumber mills.", ""),
("31", "millwork-manufacturers", "Millwork Manufacturers", "321918",
 {"321911": "Wood window and door plants run the same moulders, CNC and finishing lines and sell through the same dealer channel.",
  "321999": "Other wood product makers (dowels, turnings, components) run the same machining and finishing work."},
 "Not `cabinet-and-millwork-shops` (custom project work): covers production millwork, mouldings, wood flooring, windows and doors sold through dealers.", ""),
("31", "pallet-manufacturers", "Pallet Manufacturers", "321920", {},
 "Not `warehouse-3pl`: covers new and recycled pallet and crate makers selling to shippers on per-unit price, exposed to lumber swings and pallet-pool competition.", ""),
("31", "factory-built-home-builders", "Factory-Built Home Builders", "321991",
 {"321992": "Modular and prefab wood building makers run the same factory-line construction and shipping, under state modular codes instead of the HUD code."},
 "Not `manufactured-home-dealers` or `general-contractors`: covers factories building HUD-code manufactured homes, modular homes and panelised buildings.", ""),
("31", "pulp-and-paper-mills", "Pulp & Paper Mills", "322120",
 {"322110": "Pulp mills are mostly integrated into paper mills, with the same digesters, recovery boilers and mill crews.",
  "322130": "Paperboard mills run the same machines, wet ends and recovery operations."},
 "Not `paperboard-packaging-makers` or `paper-converters`: covers integrated pulp, paper and paperboard mills.", ""),
("31", "paperboard-packaging-makers", "Paperboard Packaging Makers", "322211",
 {"322212": "Folding carton plants print, die-cut and glue paperboard boxes for the same CPG buyers.",
  "322219": "Other paperboard container makers (tubes, drums, cores) convert the same board for the same buyers."},
 "Not `pulp-and-paper-mills` or `printing-shops`: covers corrugated box plants, sheet plants and folding-carton converters.", ""),
("31", "paper-converters", "Paper Converters", "322299",
 {"322220": "Paper bag and coated-paper makers convert parent rolls on the same slitting, coating and bag lines.",
  "322291": "Tissue and sanitary paper converters run the same roll-converting lines.",
  "322230": "Stationery makers convert paper into envelopes, notebooks and forms on the same lines."},
 "Not `pulp-and-paper-mills`: covers converters that turn parent rolls into bags, labels, tissue products, envelopes and other paper goods.", ""),
("31", "petroleum-refineries", "Petroleum Refineries", "324110",
 {"324199": "Coke and calcined petroleum coke plants run refining-adjacent thermal processes, mostly at or beside refineries."},
 "Not `petrochemical-plants` or `fuel-distributors`: covers crude oil refineries whose crude-slate selection, unit optimisation and turnarounds decide margin.", ""),
("31", "asphalt-plants", "Asphalt Plants", "324121", {},
 "Not `paving-contractors` or `highway-contractors`: covers hot-mix asphalt plants producing paving mix to DOT specs, often owned by paving contractors or aggregate producers.", ""),
("31", "lubricant-blenders", "Lubricant Blenders", "324191", {},
 "Not `petroleum-refineries`: covers blenders and packagers of lubricating oils and greases who formulate to OEM and API specs.", ""),
("31", "petrochemical-plants", "Petrochemical Plants", "325110",
 {"325194": "Cyclic crude and wood-chemical plants run the same continuous chemical process units.",
  "325199": "Other basic organic chemical plants run the same continuous process units for the same industrial buyers."},
 "Not `petroleum-refineries` or `specialty-chemical-blenders`: covers olefins, aromatics and basic organic chemical plants.", ""),
("31", "industrial-gas-producers", "Industrial Gas Producers", "325120", {},
 "Not `chemical-distributors`: covers air-separation and hydrogen producers selling oxygen, nitrogen, argon, CO2 and hydrogen by pipeline, bulk and cylinder.", ""),
("31", "inorganic-chemical-plants", "Inorganic Chemical Plants", "325180",
 {"325130": "Dye and pigment plants run the same batch and continuous inorganic chemistry for the same industrial buyers."},
 "Not `petrochemical-plants`: covers chlor-alkali, acid, pigment and other inorganic chemical plants.", ""),
("31", "ethanol-plants", "Ethanol Plants", "325193", {},
 "Not `petroleum-refineries` or `grain-elevators`: covers corn-ethanol biorefineries, many farmer-owned, whose fermentation yield and distillers-grains sales decide margin.", ""),
("31", "polymer-producers", "Polymer Producers", "325211",
 {"325212": "Synthetic rubber plants polymerise the same monomers in the same kind of reactors.",
  "325220": "Synthetic fiber plants polymerise and spin the same polymers."},
 "Not `plastic-molders` or `plastic-extruders`: covers resin, synthetic rubber and synthetic fiber producers.", ""),
("31", "fertilizer-plants", "Fertilizer Plants", "325311",
 {"325312": "Phosphate fertilizer plants run the same continuous process and sell into the same ag-retail channel."},
 "Not `ag-input-retailers`: covers nitrogen and phosphate fertilizer plants.", ""),
("31", "compost-producers", "Compost Producers", "325315", {},
 "Not `landfill-operators` or `recycling-facilities`: covers composting facilities that turn food and yard waste into compost under state permits and earn on both tipping fees and product.", ""),
("31", "crop-protection-manufacturers", "Crop Protection Manufacturers", "325320", {},
 "Not `ag-input-retailers` or `fertilizer-plants`: covers pesticide and biological crop-protection makers and formulators under EPA FIFRA registration.", ""),
("31", "supplement-manufacturers", "Supplement Manufacturers", "325411", {},
 "Not `supplement-stores` or `pharmaceutical-manufacturers`: covers dietary supplement and botanical makers, private-label contract makers included, under FDA 21 CFR 111.", ""),
("31", "pharmaceutical-manufacturers", "Pharmaceutical Manufacturers", "325412", {},
 "Not `biotech-research-firms` or `pharmacy-independents`: covers drug-product makers and CDMOs (generic, branded small-molecule, OTC) under FDA cGMP.", ""),
("31", "biologics-manufacturers", "Biologics Manufacturers", "325414", {},
 "Not `pharmaceutical-manufacturers`: covers makers of vaccines, antibodies and cell and gene therapies whose cell-culture processes and lot release run under FDA biologics rules.", ""),
("31", "coatings-and-adhesives-makers", "Coatings & Adhesives Makers", "325510",
 {"325520": "Adhesive makers formulate batch chemistry for the same industrial buyers with the same lab, QC and performance testing.",
  "325910": "Printing ink makers formulate and color-match batches the same way."},
 "Not `paint-stores`: covers paint, coatings, adhesive and ink formulators.", ""),
("31", "cleaning-chemical-makers", "Cleaning Chemical Makers", "325611",
 {"325612": "Polish and sanitation-goods makers blend the same surfactant chemistry for the same retail and institutional buyers.",
  "325613": "Surfactant makers supply and often run the same blending operations."},
 "Not `cleaning-companies` or `business-supplies-distributors`: covers soap, detergent and cleaning-product makers, private label and institutional included.", ""),
("31", "cosmetics-manufacturers", "Cosmetics Manufacturers", "325620", {},
 "Not `beauty-supply-stores` or `d2c-brand-operators`: covers cosmetics, personal-care and fragrance makers and private-label labs under MoCRA.", ""),
("31", "specialty-chemical-blenders", "Specialty Chemical Blenders", "325998",
 {"325992": "Photographic chemical and toner makers blend and package specialty formulations the same way."},
 "Not `chemical-distributors`: covers formulators of water-treatment chemicals, de-icers, additives and other specialty preparations.", ""),
("31", "plastic-film-and-bag-makers", "Plastic Film & Bag Makers", "326112",
 {"326111": "Bag and pouch makers convert the same blown and cast film on the same lines.",
  "326113": "Unlaminated film and sheet extruders run the same film lines."},
 "Not `plastic-extruders`: covers flexible-packaging film, bag and pouch makers.", ""),
("31", "plastic-extruders", "Plastic Extruders", "326121",
 {"326122": "Pipe and fitting extruders run the same extrusion lines and dies.",
  "326130": "Laminated plastic plate and sheet makers press and extrude for the same industrial buyers."},
 "Not `plastic-molders`: covers profile, pipe and sheet extruders.", ""),
("31", "foam-product-makers", "Foam Product Makers", "326150",
 {"326140": "Polystyrene foam makers mould and cut foam for the same packaging and construction buyers."},
 "Not `plastic-molders`: covers urethane and polystyrene foam fabricators.", ""),
("31", "plastic-molders", "Plastic Molders", "326199",
 {"326160": "Bottle makers blow-mould on the same kind of machines for the same custom-molding buyers."},
 "Not `contract-manufacturing`: covers custom and proprietary injection and blow molders.", ""),
("31", "tire-manufacturers", "Tire Manufacturers", "326211", {},
 "Not `tire-dealers` or `tire-retreaders`: covers tire plants.", ""),
("31", "tire-retreaders", "Tire Retreaders", "326212", {},
 "Not `tire-manufacturers`: covers commercial truck tire retreaders who inspect casings and rebuild treads for fleets.", ""),
("31", "rubber-product-makers", "Rubber Product Makers", "326299",
 {"326220": "Hose and belt makers mix, mould and extrude the same compounds.",
  "326291": "Mechanical rubber goods makers mould the same compounds for OEMs.",
  "339991": "Gasket and seal makers mould and die-cut the same elastomers for the same industrial buyers."},
 "Not `plastic-molders`: covers rubber compounders and molders.", ""),
("31", "ceramics-and-refractory-makers", "Ceramics & Refractory Makers", "327120",
 {"327110": "Pottery, sanitaryware and technical ceramics are formed and kiln-fired the same way.",
  "327910": "Abrasive makers press and fire bonded abrasives in the same kilns.",
  "327999": "Other nonmetallic mineral products are formed and fired the same way."},
 "Not `building-products-plants`: covers brick, refractory, ceramic and abrasive makers whose kilns are the core.", ""),
("31", "glass-manufacturers", "Glass Manufacturers", "327213",
 {"327211": "Flat glass plants run the same melting furnaces.",
  "327212": "Pressed and blown glassware plants run the same furnaces and forming."},
 "Not `glass-fabricators`: covers glass melting plants.", ""),
("31", "glass-fabricators", "Glass Fabricators", "327215", {},
 "Not `glass-manufacturers` or `glazing-contractors`: covers shops that cut, temper, laminate and assemble insulating glass from purchased glass.", ""),
("31", "cement-and-lime-plants", "Cement & Lime Plants", "327310",
 {"327410": "Lime plants run the same kilns, quarry feed and bulk shipping."},
 "Not `ready-mix-concrete-producers`: covers cement and lime kilns.", ""),
("31", "ready-mix-concrete-producers", "Ready-Mix Concrete Producers", "327320", {},
 "Not `concrete-contractors`: covers ready-mix plants whose mix design and truck dispatch run the business.", ""),
("31", "concrete-products-plants", "Concrete Products Plants", "327390",
 {"327331": "Block and brick plants cast the same products.",
  "327332": "Concrete pipe plants cast in the same yards."},
 "Not `ready-mix-concrete-producers`: covers precast and concrete products plants.", ""),
("31", "building-products-plants", "Building Products Plants", "327420",
 {"324122": "Asphalt shingle plants run continuous lines selling to the same distributors and contractors.",
  "327993": "Mineral wool plants run the same continuous lines into the same channel."},
 "Not `building-material-dealers`: covers gypsum, shingle and insulation plants.", ""),
("31", "stone-countertop-fabricators", "Stone Countertop Fabricators", "327991", {},
 "Not `dimension-stone-quarries` or `finish-carpentry-contractors`: covers granite and quartz countertop shops that template, cut and install, under OSHA's silica rule.", ""),
("31", "steel-mills", "Steel Mills", "331110",
 {"331221": "Rolled shape mills roll the same steel.",
  "331210": "Pipe and tube mills form and weld the same steel.",
  "331222": "Wire drawers draw the same rod."},
 "Not `metal-service-centers` or `metal-fabrication`: covers steel mills and steel processing mills.", ""),
("31", "nonferrous-metal-mills", "Nonferrous Metal Mills", "331410",
 {"331313": "Primary aluminum smelters run the same melt, cast and pot-line operations.",
  "331314": "Secondary aluminum smelters remelt scrap the same way.",
  "331315": "Aluminum sheet, plate and foil mills roll the same metal.",
  "331420": "Copper rolling and drawing mills roll and draw the same way.",
  "331491": "Other nonferrous rolling mills roll and draw the same way.",
  "331492": "Secondary nonferrous smelters remelt scrap the same way."},
 "Not `aluminum-extruders` or `scrap-metal-recyclers`: covers aluminum, copper and other nonferrous smelters, refiners and rolling mills.", ""),
("31", "aluminum-extruders", "Aluminum Extruders", "331318", {},
 "Not `nonferrous-metal-mills` or `metal-fabrication`: covers extruders that press billet through custom dies into profiles.", ""),
("31", "sand-casting-foundries", "Sand Casting Foundries", "331511",
 {"331513": "Steel foundries run the same sand-mould pattern, melt, pour and finish.",
  "331524": "Aluminum foundries run the same sand and permanent-mould casting.",
  "331529": "Other nonferrous foundries run the same casting."},
 "Not `metal-fabrication`: covers iron, steel and aluminum sand-casting foundries.", ""),
("31", "investment-casting-foundries", "Investment Casting Foundries", "331512", {},
 "Not `sand-casting-foundries`: covers lost-wax investment casters.", ""),
("31", "die-casting-shops", "Die Casting Shops", "331523", {},
 "Not `sand-casting-foundries`: covers high-pressure die casters.", ""),
("31", "forging-shops", "Forging Shops", "332111",
 {"332112": "Nonferrous forgers run the same presses, hammers, die design and heat treatment for the same aerospace, auto and industrial buyers.",
  "332117": "Powder metallurgy shops press and sinter net-shape parts for the same auto and industrial buyers, competing for the same part numbers."},
 "Not `metal-fabrication` or `sand-casting-foundries`: covers open- and closed-die forgers and powder-metal part makers, where die life and forging-temperature judgement decide scrap.", ""),
("31", "tool-and-hardware-makers", "Tool & Hardware Makers", "332510",
 {"332215": "Cookware, cutlery and flatware makers stamp, forge and finish metal consumer goods for the same retail and distributor buyers.",
  "332216": "Saw blade and hand tool makers forge, heat-treat and finish for the same hardware and industrial channel.",
  "333991": "Power tool makers sell through the same hardware, home-center and industrial-supply channel, often under the same brands."},
 "Not `hardware-stores` or `fastener-manufacturers`: covers makers of hand and power tools, cookware, cutlery, locks and builders' hardware sold through retail and distribution.", ""),
("31", "metal-container-makers", "Metal Container Makers", "332431",
 {"332439": "Drum, pail and gas-cylinder makers form, seam and test steel containers on the same kind of lines for the same filler customers."},
 "Not `paperboard-packaging-makers` or `metal-fabrication`: covers can, drum, pail and cylinder makers supplying beverage, food and chemical fillers on long contracts.", ""),
("31", "fastener-manufacturers", "Fastener Manufacturers", "332722",
 {"339993": "Button, pin, snap and zipper makers cold-form, stamp and mould small fastening parts at high volume for OEM and apparel buyers, the same process economics."},
 "Not `industrial-distributors` or `metal-fabrication`: covers cold-heading and thread-rolling shops making bolts, screws, rivets and other fasteners to spec, with lot traceability.", ""),
("31", "valve-manufacturers", "Valve Manufacturers", "332911",
 {"332919": "Other metal valve and pipe-fitting makers machine, pressure-test and certify to the same API and ASME standards for the same plant and EPC buyers."},
 "Not `fluid-power-manufacturers` or `plumbing-products-makers`: covers industrial valve and fitting makers selling to refineries, chemical plants, water utilities and EPC contractors.", ""),
("31", "plumbing-products-makers", "Plumbing Products Makers", "332913",
 {"326191": "Plastic and fiberglass tub, shower and fixture makers sell through the same plumbing wholesalers and showrooms to the same plumbers and builders."},
 "Not `plumbing-and-hvac-distributors` or `ceramics-and-refractory-makers`: covers faucet, fitting, trim and plastic fixture makers selling through plumbing distribution.", ""),
("31", "firearms-manufacturers", "Firearms Manufacturers", "332994",
 {"332992": "Small arms ammunition makers sell under the same ATF and FFL/SOT licensing through the same distributors and retailers."},
 "Not `defense-systems-manufacturers` or `sporting-goods-stores`: covers civilian and law-enforcement firearms and small-arms ammunition makers.", ""),
("31", "farm-equipment-manufacturers", "Farm Equipment Manufacturers", "333111",
 {"333112": "Lawn, garden and turf equipment makers sell through the same farm and outdoor-power dealer networks, often as divisions of the same OEMs."},
 "Not `farm-equipment-dealers`: covers tractor, combine, implement and turf equipment makers selling through franchised dealers.", ""),
("31", "heavy-machinery-manufacturers", "Heavy Machinery Manufacturers", "333120",
 {"333131": "Mining machinery is made largely by the same OEMs on the same platforms (haul trucks, loaders, drills) and sold through the same dealers."},
 "Not `heavy-equipment-dealers` or `equipment-rental-companies`: covers construction and mining machinery OEMs and their attachment makers.", ""),
("31", "oilfield-equipment-manufacturers", "Oilfield Equipment Manufacturers", "333132", {},
 "Not `oil-gas-field-services` or `heavy-machinery-manufacturers`: covers makers of rigs, pressure-pumping units, wellheads and downhole tools sold to drillers and service companies on a boom-bust cycle.", ""),
("31", "industrial-machinery-builders", "Industrial Machinery Builders", "333248",
 {"333241": "Food machinery builders design and build engineer-to-order machines with the same quote, design, build, FAT and field-service workflow.",
  "333243": "Woodworking and paper machinery builders run the same engineer-to-order workflow.",
  "333993": "Packaging machinery builders run the same engineer-to-order workflow for the same plant buyers.",
  "333994": "Industrial furnace and oven builders run the same engineer-to-order workflow.",
  "333519": "Rolling mill and other metalworking machinery builders run the same engineer-to-order workflow.",
  "333998": "Other general-purpose machinery builders run the same engineer-to-order workflow."},
 "Not `contract-manufacturing` or `machine-tool-builders`: covers engineer-to-order builders of production machinery (packaging, food, process, furnace) sold to plants with acceptance testing and field service.", ""),
("31", "semiconductor-equipment-makers", "Semiconductor Equipment Makers", "333242", {},
 "Not `semiconductor-manufacturers` or `industrial-machinery-builders`: covers wafer-fab tool makers (deposition, etch, lithography support, metrology) whose installed-base service and process recipes are the business.", ""),
("31", "commercial-equipment-manufacturers", "Commercial Equipment Manufacturers", "333310", {},
 "Not `restaurant-suppliers` or `business-equipment-dealers`: covers makers of commercial cooking, laundry, vending, car-wash and optical equipment sold to service businesses through dealers.", ""),
("31", "hvac-equipment-manufacturers", "HVAC Equipment Manufacturers", "333415",
 {"333413": "Fan, blower and air-purification makers sell into the same HVAC distribution and mechanical-contractor channel.",
  "333414": "Boiler and heating equipment makers sell into the same channel under the same DOE efficiency rules."},
 "Not `hvac-contractors` or `plumbing-and-hvac-distributors`: covers makers of furnaces, AC, heat pumps, boilers, fans and commercial refrigeration.", ""),
("31", "tool-die-and-mold-shops", "Tool, Die & Mold Shops", "333514",
 {"333511": "Industrial mold makers build one-off tooling with the same toolmakers, CNC and EDM equipment and tryout process as die shops."},
 "Not `metal-fabrication` or `plastic-molders`: covers tool-and-die and mold shops building one-off production tooling, the most skill-dense shops in manufacturing.", ""),
("31", "machine-tool-builders", "Machine Tool Builders", "333517",
 {"333515": "Cutting tool and accessory makers sell to the same machine shops through the same distributors and applications engineers.",
  "333992": "Welding and soldering equipment makers sell to the same metalworking shops through the same distributors."},
 "Not `metal-fabrication` or `industrial-machinery-builders`: covers builders of CNC machine tools, cutting tools and welding equipment sold to metalworking shops through distributors.", ""),
("31", "engine-and-turbine-makers", "Engine & Turbine Makers", "333611",
 {"333618": "Other engine makers (diesel, gas and marine engines) build prime movers for the same OEM and power-generation buyers with the same aftermarket model."},
 "Not `power-equipment-manufacturers` or `vehicle-manufacturers`: covers turbine, generator-set and stationary and marine engine makers.", ""),
