SKIP = {
    "521110": "Central banking is the Federal Reserve System, a single statutory institution; there is no firm population to build for.",
    "525920": "Trusts, estates and agency accounts are legal entities with no staff; their administration is done by trust-companies and estate lawyers.",
    "532282": "Video tape and disc rental has essentially no operators left (Redbox kiosks shut in 2024; one Blockbuster store remains).",
    "551111": "Bank holding companies are legal shells; the operating work sits in the bank subsidiaries (community-banks).",
    "551112": "Holding company offices are legal shells; the operating work sits in subsidiaries in other industries.",
    "551114": "Corporate and regional head offices are functions of firms classified in other industries, not a firm type of their own.",
    "491110": "The Postal Service is a single federal operator (USPS); contract postal units and mail centers are covered under private-mail-centers.",
    "814110": "Private households that employ domestic workers are not firms; household-employer payroll is served by payroll-platforms.",
    "927110": "Space research administration is a single federal agency (NASA); its contractors sit in manufacturing and R&D industries.",
    "928110": "National security is a single federal department (DoD); its suppliers sit in defense manufacturing and services industries.",
    "928120": "International affairs is a single federal department (State, with USAID); there is no firm population to build for.",
}


def build():
    rest_text = open("_rest-of-the-industries.md").read().split("## Already covered")[0]
    rest = dict(re.findall(r"^\| (\d{6}) \| (.*?) \| `", rest_text, re.M))
    rows, seen = [], {}

    def add(code, decision, slug, reason):
        if code in seen:
            sys.exit(f"DUPLICATE {code}: {seen[code]} and {slug}")
        if code not in rest:
            sys.exit(f"UNKNOWN CODE {code}")
        seen[code] = slug or decision
        rows.append((code, rest[code], code[:2], decision, slug, reason))

    slugs = set()
    for sector, slug, name, new, merges, boundary, new_reason in IND:
        if slug in slugs:
            sys.exit(f"DUPLICATE SLUG {slug}")
        slugs.add(slug)
        add(new, "new", slug, new_reason)
        for code, why in merges.items():
            add(code, "merge", slug, why)
    for code, (slug, why) in COVERED.items():
        add(code, "covered", slug, why)
    for code, why in SKIP.items():
        add(code, "skip", "", why)
    missing = sorted(set(rest) - set(seen))
    if missing:
        sys.exit("UNTRIAGED " + " ".join(missing))

    rows.sort()
    with open("_state/rest/naics-triage.tsv", "w") as f:
        f.write("naics\ttitle\tsector\tdecision\tslug\treason\n")
        for r in rows:
            f.write("\t".join(r) + "\n")

    by_sector = {s: [] for s in ORDER}
    for e in IND:
        by_sector[e[0]].append(e)
    by_sector["31"].sort(key=lambda e: e[3])
    order, batch, q = 0, 0, []
    for s in ORDER:
        items = by_sector[s]
        k = math.ceil(len(items) / 10)
        size, extra = divmod(len(items), k)
        i = 0
        for b in range(k):
            batch += 1
            n = size + (1 if b < extra else 0)
            for sector, slug, name, new, merges, boundary, _ in items[i:i + n]:
                order += 1
                codes = [new] + sorted(merges)
                cat = CAT_OVERRIDE.get(slug, CATEGORY[sector])
                q.append((str(order), str(batch), slug, name, cat, ",".join(codes), "todo", boundary))
            i += n
    with open("_state/rest/queue.tsv", "w") as f:
        f.write("order\tbatch\tslug\tname\tcategory\tnaics\tstatus\tboundary\n")
        for r in q:
            assert all("\t" not in x and "\n" not in x for x in r), r
            f.write("\t".join(r) + "\n")
    tally = {}
    for r in rows:
        tally[r[3]] = tally.get(r[3], 0) + 1
    print(f"{len(rows)} codes: {tally} | {len(q)} industries in {batch} batches")


if __name__ == "__main__":
    build()
